"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83766"],{86620(e){e.exports=JSON.parse('{"id":"F397","slug":"newton-implied-vol","name":"Newton\'s Method for Implied Volatility","subject":"Quantitative Finance","section":"Quant","topic":"Optimization methods","level":"Intermediate","aliases":["Newton Raphson","root finding","iterative solution","optimization methods"],"formula":{"latex":"\\\\sigma_{n+1}=\\\\sigma_{n}-\\\\frac{BS(\\\\sigma_{n})-\\\\text{Price}}{\\\\mathcal{V}(\\\\sigma_{n})}","also":[],"text":"Next guess = Current guess - (Model price at the guess - Market price) / Vega at the guess"},"symbols":[{"symbol":"sigma_n","meaning":"Current guess for the volatility","unit":"per year"},{"symbol":"BS()","meaning":"Black-Scholes price at that volatility","unit":"money"},{"symbol":"Vega","meaning":"Sensitivity of the option price to volatility, used as the slope","unit":"money"}],"when_to_use":"Use it to see how a numerical solver finds an answer that has no formula. Newton\'s method follows the slope: from the current guess, move to where the tangent line would hit the target. It usually settles in three to five steps. The same idea drives optimization, where it is applied to the derivative.","worked_example":{"problem":"A call (stock 100, strike 100, 1 year, rate 5%, no dividend) costs 12.50. Start from a guess of 30% volatility and do three Newton steps.","inputs":{"sp":100,"k":100,"r":5,"t":1,"q":0,"price":12.5,"s0":30},"steps":[{"label":"Starting guess","working":"0.3","value":"30.0000%"},{"label":"Step 1: guess - (price at guess - target) / vega","working":null,"value":"25.4373%"},{"label":"Step 2","working":null,"value":"25.4333%"},{"label":"Step 3","working":null,"value":"25.4333%"},{"label":"Size of the last change","working":null,"value":"0.0000%"},{"label":"Price at the final guess","working":null,"value":"12.50"}],"answer":"The guesses go 30.0000% to 25.4373%, then 25.4333% and 25.4333%. The last step changed the answer by only 0.0000%, and the price at the final guess is 12.50, matching the 12.50 target."},"calculator":{"available":true,"inputs":[{"id":"sp","label":"Stock price","unit":"money","type":"number","default":100,"hint":""},{"id":"k","label":"Strike","unit":"money","type":"number","default":100,"hint":""},{"id":"r","label":"Risk-free rate","unit":"%","type":"number","default":5,"hint":""},{"id":"t","label":"Time to expiry","unit":"years","type":"number","default":1,"hint":"","min":0.1},{"id":"q","label":"Dividend yield","unit":"%","type":"number","default":0,"hint":""},{"id":"price","label":"Market price","unit":"money","type":"number","default":12.5,"hint":""},{"id":"s0","label":"Starting guess for volatility","unit":"%","type":"number","default":30,"hint":""}],"checks":[{"expr":"price>0 and s0>0","message":"The price and the starting guess must be above zero."}],"steps":[{"id":"s0_","label":"Starting guess","expr":"s0","format":"pct4"},{"id":"s1","label":"Step 1: guess - (price at guess - target) / vega","expr":"s0-(bscall(sp, k, r, t, s0, q)-price)/(sp*exp(-q*t)*normpdf(d1(sp, k, r, t, s0, q))*sqrt(t))","format":"pct4"},{"id":"s2","label":"Step 2","expr":"s1-(bscall(sp, k, r, t, s1, q)-price)/(sp*exp(-q*t)*normpdf(d1(sp, k, r, t, s1, q))*sqrt(t))","format":"pct4"},{"id":"s3","label":"Step 3","expr":"s2-(bscall(sp, k, r, t, s2, q)-price)/(sp*exp(-q*t)*normpdf(d1(sp, k, r, t, s2, q))*sqrt(t))","format":"pct4"},{"id":"err","label":"Size of the last change","expr":"abs(s3-s2)","format":"pct4"},{"id":"check","label":"Price at the final guess","expr":"bscall(sp, k, r, t, s3, q)","format":"money"}],"results":["s3","check"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"s3":0.25433295278769913,"check":12.5}},"finder":{"finds":"How an iterative solver closes in on an answer","needs":"Option inputs, market price, starting guess"},"related":[{"slug":"implied-volatility","name":"Implied Volatility"},{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price"},{"slug":"option-greeks","name":"Option Greeks: Delta, Gamma, Vega, Theta, Rho"}],"related_ids":["F335","F331","F332"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>\u03C3</mi><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow></msub><mo>=</mo><msub><mi>\u03C3</mi><mi>n</mi></msub><mo>\u2212</mo><mfrac><mrow><mi>B</mi><mi>S</mi><mo stretchy=\\"false\\">(</mo><msub><mi>\u03C3</mi><mi>n</mi></msub><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mtext>Price</mtext></mrow><mrow><mi mathvariant=\\"script\\">V</mi><mo stretchy=\\"false\\">(</mo><msub><mi>\u03C3</mi><mi>n</mi></msub><mo stretchy=\\"false\\">)</mo></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\sigma_{n+1}=\\\\sigma_{n}-\\\\frac{BS(\\\\sigma_{n})-\\\\text{Price}}{\\\\mathcal{V}(\\\\sigma_{n})}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"netting-efficiency","name":"Netting Efficiency in Payment Clearing"},"next":{"slug":"noise-variance-share","name":"Noise Trading: Share of Price Variance Explained by Fundamentals"},"lesson":null,"total":522}')}}]);